def tokenize(line):
    """Split a command line into words. Double quotes keep spaces inside one word."""
    # TODO: walk the line one character at a time.
    # Track: the word so far, whether you're inside quotes, and whether a word has started
    # (so that "" still counts as a word, an empty one).
    return line.split()


def handle(line):
    try:
        words = tokenize(line)
    except ValueError as e:
        return f"ERR {e}"
    if not words:
        return None
    cmd, args = words[0].upper(), words[1:]
    if cmd == "PING":
        return "PONG"
    if cmd == "ECHO":
        return " ".join(args)
    return f"ERR unknown command '{words[0]}'"

