// app.js: your server, on your own framework. client.js starts it with require("./app").
const express = require("./express");

const app = express();

const notes = [
  { id: 1, text: "buy tulip bulbs" },
  { id: 2, text: "water the trellis" },
];
let nextId = 3;

// every request, logged once its answer has gone out
app.use((req, res, next) => {
  res.on("finish", () => console.log(`${req.method} ${req.originalUrl} → ${res.statusCode}`));
  next();
});
app.use(express.json());

// loads the note named in the path onto req, or answers 404: any route with :id can use it
function findNote(req, res, next) {
  req.note = notes.find((n) => n.id === Number(req.params.id));
  if (!req.note) return res.status(404).json({ error: "no such note" });
  next();
}

app.get("/", (req, res) => res.send("hello from trellis"));
app.get("/health", (req, res) => res.send("ok"));

app.get("/notes", (req, res) => {
  const q = (req.query.q || "").toLowerCase();
  res.json(notes.filter((n) => n.text.toLowerCase().includes(q)));
});

app.get("/notes/:id", findNote, (req, res) => res.json(req.note));

app.post("/notes", (req, res) => {
  const text = req.body && req.body.text;
  if (typeof text !== "string" || !text.trim()) return res.status(400).json({ error: "text is required" });
  const note = { id: nextId++, text: text.trim() };
  notes.push(note);
  res.status(201).set("Location", `/notes/${note.id}`).json(note);
});

app.delete("/notes/:id", findNote, (req, res) => {
  notes.splice(notes.indexOf(req.note), 1);
  res.status(204).end();
});

app.listen(3000, () => console.log("listening on http://localhost:3000"));

