const express = require("express");
const app = express();
app.use(express.json());
app.post("/echo", (req, res) => res.json({ body: req.body === undefined ? "none" : req.body }));
app.listen(3001);
const at = { port: 3001 };
let r = await request("POST /echo", { a: 1, list: [1, 2] }, at);
assert(r.json && r.json.body.a === 1 && r.json.body.list[1] === 2, "express.json() parses a JSON body into req.body");
r = await request("POST /echo", "not json", { ...at, headers: { "Content-Type": "text/plain" } });
assert(r.json && r.json.body === "none", "A body that isn't JSON is left alone: req.body stays undefined");
r = await request("POST /echo", undefined, at);
assert(r.json && r.json.body === "none", "No body and no Content-Type: nothing to parse");
r = await request("POST /echo", '{"a": 1', { ...at, headers: { "Content-Type": "application/json" } });
assert(r.status === 400, "Broken JSON: 400 Bad Request");
r = await request("POST /echo", '{"a": 2}', { ...at, headers: { "Content-Type": "application/json; charset=utf-8" } });
assert(r.json && r.json.body.a === 2, "A Content-Type with a charset is still JSON");
r = await request("POST /notes", { text: "  prune the roses " });
assert(r.status === 201 && r.json && r.json.id === 3 && r.json.text === "prune the roses", "POST /notes makes note 3, trimmed, with 201 Created");
assert(r.headers.location === "/notes/3", "and a Location header saying where it lives");
r = await request("GET /notes/3");
assert(r.json && r.json.text === "prune the roses", "GET /notes/3 finds it");
r = await request("POST /notes", { text: "   " });
assert(r.status === 400 && r.json && r.json.error === "text is required", 'Blank text: 400 {"error": "text is required"}');
r = await request("POST /notes", { words: "hi" });
assert(r.status === 400, "No text field at all: 400 too");
r = await request("POST /notes", '{"text": ', { headers: { "Content-Type": "application/json" } });
assert(r.status === 400 && r.json && r.json.error === "invalid JSON", 'Broken JSON in app.js: 400 {"error": "invalid JSON"}');
r = await request("DELETE /notes/1");
assert(r.status === 204 && r.text === "", "DELETE /notes/1: 204 No Content");
r = await request("GET /notes/1");
assert(r.status === 404, "and it's gone");

