const app = express();
app.use(express.json());
app.get("/sync", () => { throw new Error("sync oops"); });
app.get("/async", async () => { await null; throw new Error("async oops"); });
app.get("/teapot", (req, res, next) => { const e = new Error("I only make tea"); e.status = 418; next(e); });
app.get("/caught", () => { throw new Error("to the handler"); });
app.use("/caught", (err, req, res, next) => res.status(500).json({ handled: err.message }));
