let r = await request("GET /sync", undefined, at);
assert(r.status === 500 && r.text === "Internal Server Error", "A handler that throws gets a 500, not a crash");
r = await request("GET /async", undefined, at);
assert(r.status === 500, "So does an async handler whose promise rejects");
r = await request("GET /teapot", undefined, at);
assert(r.status === 418 && r.text === "I only make tea", "next(err) with err.status 418: that status, and the message, since it's a 4xx");
r = await request("GET /caught", undefined, at);
assert(r.json && r.json.handled === "to the handler", "An error handler is a layer with four arguments: (err, req, res, next)");
r = await request("GET /sync", undefined, at);
assert(r.status === 500, "The server is still up after all of that");
