// A router: a stack of layers, and the next() that walks it. It's a handler itself, (req, res, next),
// so it can be mounted inside another router: app.use("/notes", notes).
function Router() {
  const stack = [];   // layers: { method (null for use), re, keys, handler }, in the order they were added

  function router(req, res, out) {
    const url = req.url, baseUrl = req.baseUrl || "";
    let i = 0;
    function next(err) {
      // a layer below may have cut a prefix off the URL: put it back before going on
      req.url = url;
      req.baseUrl = baseUrl;
      req.path = url.split("?")[0];
      while (i < stack.length) {
        const layer = stack[i++];
        if (layer.method && layer.method !== req.method) continue;
        const m = layer.re.exec(req.path);
        if (!m) continue;
        // with an error, only error handlers (four arguments) run; without one, they're skipped
        if (Boolean(err) !== (layer.handler.length === 4)) continue;
        req.params = {};
        layer.keys.forEach((k, j) => { req.params[k] = decodeURIComponent(m[j + 1]); });
        if (!layer.method && m[0]) {
          // use("/notes", ...): inside, /notes/7 is /7, and the prefix moves to baseUrl
          req.baseUrl = baseUrl + m[0];
          req.url = url.slice(m[0].length);
          if (!req.url.startsWith("/")) req.url = "/" + req.url;
          req.path = req.url.split("?")[0];
        }
        try {
          const result = err ? layer.handler(err, req, res, next) : layer.handler(req, res, next);
          // an async handler returns a promise: if it rejects, that's an error too
          if (result && typeof result.then === "function") result.then(null, next);
        } catch (e) {
          next(e);
        }
        return;
      }
      out(err);
    }
    next();
  }

  router.use = (path, ...handlers) => {
    if (typeof path === "function") {
      handlers.unshift(path);
      path = "/";
    }
    for (const handler of handlers) stack.push({ method: null, ...compile(path, true), handler });
    return router;
  };

  for (const m of METHODS) {
    router[m] = (path, ...handlers) => {
      for (const handler of handlers) stack.push({ method: m.toUpperCase(), ...compile(path), handler });
      return router;
    };
  }

  return router;
}

// The app is a router that can start a server, and that finishes whatever nobody answered.
function express() {
  const router = Router();

  function app(req, res, next) {
    if (next) return router(req, res, next);   // mounted inside another app
    helpers(res);
    req.originalUrl = req.url;
    req.baseUrl = "";
    req.query = Object.fromEntries(new URL(req.url, "http://localhost").searchParams);
    req.params = {};
    router(req, res, (err) => done(err, req, res));
  }

  app.use = (...args) => {
    router.use(...args);
    return app;
  };
  for (const m of METHODS) {
    app[m] = (...args) => {
      router[m](...args);
      return app;
    };
  }
  app.listen = (...args) => http.createServer(app).listen(...args);

  return app;
}

// express.json(): a middleware that reads a JSON body into req.body, once, for every route after it
express.json = function json() {
  return (req, res, next) => {
    const type = (req.headers["content-type"] || "").split(";")[0].trim().toLowerCase();
