assert(typeof express.Router === "function", "express.Router() makes a router");
const app = express();
const users = express.Router();
users.get("/", (req, res) => res.send("all users"));
users.get("/:id", (req, res) => res.json({ id: req.params.id, baseUrl: req.baseUrl, url: req.url, originalUrl: req.originalUrl }));
const api = express.Router();
api.use("/users", users);
app.use("/api", api);
app.get("/api/other", (req, res) => res.send("after the router"));
app.listen(3001);
const at = { port: 3001 };
let r = await request("GET /api/users", undefined, at);
assert(r.text === "all users", "app.use('/api', api) and api.use('/users', users): /api/users reaches users at /");
r = await request("GET /api/users/7?x=1", undefined, at);
assert(r.json && r.json.id === "7", "Params work inside a mounted router");
assert(r.json.baseUrl === "/api/users" && r.json.url === "/7?x=1", "req.baseUrl is where it's mounted, and req.url is the rest");
assert(r.json.originalUrl === "/api/users/7?x=1", "req.originalUrl is the whole thing, untouched");
r = await request("GET /api/other", undefined, at);
assert(r.text === "after the router", "When a router doesn't answer, the app carries on after it, with the whole path");
